mapper.select:
select

from CHB_MONTH_REPORT_SUB


        to_char(CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') >= #{submitDeadLineStart,jdbcType=VARCHAR}


        and to_char(CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



            #{item,jdbcType=VARCHAR}




            #{item,jdbcType=VARCHAR}




            #{item,jdbcType=VARCHAR}



        and to_char(STATUS_DATE,'yyyy-MM-dd') >= #{statusDateStart,jdbcType=VARCHAR}


        and to_char(STATUS_DATE,'yyyy-MM-dd') <= #{statusDateEnd,jdbcType=VARCHAR}


        and to_char(SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDateStart,jdbcType=VARCHAR}


        and to_char(SUBMIT_TIME,'yyyy-MM-dd') <= #{submitDateEnd,jdbcType=VARCHAR}


        and TERMID >= #{termidDateStart,jdbcType=VARCHAR}


        and TERMID <= #{termidDateEnd,jdbcType=VARCHAR}



            #{submitFeedbackStatus,jdbcType=VARCHAR}



        and SEND_STATUS = #{sendStatus,jdbcType=VARCHAR}


        and TERMID = #{termid,jdbcType=VARCHAR}


        and to_char(ENDDATE,'yyyy-MM') = #{enddate,jdbcType=VARCHAR}


ORDER BY STATUS_DATE

mapper.insert:
insert into CHB_MONTH_REPORT_SUB ( REPORTUUID,TERMID, REPORTTYPE, STARTDATE, ENDDATE, ISSUE_PARTY_ID, ISSUE_PARTY_NAME, REPORTFREQU, SUBMIT_TIME, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, STATUS, SEND_STATUS, STATUS_DATE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, CREATE_DEPT) select REPORTUUID, TERMID, REPORTTYPE, STARTDATE, ENDDATE, ISSUE_PARTY_ID, ISSUE_PARTY_NAME, REPORTFREQU, SUBMIT_TIME, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, STATUS, SEND_STATUS, STATUS_DATE, CREATE_USER, his.CREATE_TIME, UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, CREATE_DEPT from CHB_MONTH_REPORT_SUB_HIS his INNER join ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_MONTH_REPORT_SUB_HIS
TERMID IN
#{regist.termid,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME

